["diff --git a/README.md b/README.md
index 93a6e28..0b6c661 100644
--- a/README.md
+++ b/README.md
@@ -212,6 +212,44 @@ Easy State monitors which store properties are used inside each component's rend

 Triggered renders are passed to React for execution, there is no `forceUpdate` behind the scenes. This means that component lifecycle hooks behave as expected and that React Fiber works nicely together with Easy State. On top of this, you can use your favorite testing frameworks without any added hassle.

+### My component renders multiple times unnecessarily
+
+If you mutate your stores inside React event handlers, this will never happen.
+
+If you mutate your stores multiple times synchronously from outside event handlers, it can happen though. You can wrap the mutating code with `ReactDOM.flushSync` to batch the updates and trigger a single re-render only. (It works similarly to MobX's actions.)
+
+```js
+import React from 'react';
+import ReactDOM from 'react-dom';
+import { view, store } from 'react-easy-state';
+
+const user = store({ name: 'Bob', age: 30 });
+
+function mutateUser() {
+  user.name = 'Ann';
+  user.age = 32;
+}
+
+// this renders the component 2 times
+mutateUser();
+// this renders the component only once, after all the mutations
+ReactDOM.flushSync(mutateUser);
+
+// clicking on the inner div renders the component only once,
+// because mutateUser is invoked as an event handler
+export default view(() => (
+  <div onClick={mutateUser}>
+    name: {user.name}, age: {user.age}
+  </div>
+));
+```
+
+This will not be necessary once React's new scheduler is ready. It currently batches `setState` calls inside event handlers only, but this will change soon.
+
+> We realize it's inconvenient that the behavior is different depending on whether you're in an event handler or not. This will change in a future React version that will batch all updates by default (and provide an opt-in API to flush changes synchronously). Until we switch the default behavior (potentially in React 17), there is an API you can use to force batching.
+
+You can find the whole post by Dan Abramov [here](https://stackoverflow.com/a/48610973). Once the new default React scheduler is ready, you won't have to worry about multiple renders. Until then you can use `ReactDOM.flushSync` or just let it go, if you do not experience performance issues.
+
 ### How do I derive local stores from props (getDerivedStateFromProps)?

 Components wrapped with `view` have an extra static `deriveStoresFromProps` lifecycle method, which works similarly to the vanilla `getDerivedStateFromProps`.
", "diff --git a/__tests__/autoEffect.no-hook.test.jsx b/__tests__/autoEffect.no-hook.test.jsx
new file mode 100644
index 0000000..2f1f9e6
--- /dev/null
+++ b/__tests__/autoEffect.no-hook.test.jsx
@@ -0,0 +1,48 @@
+import React, { Component } from 'react';
+import { render, cleanup } from '@testing-library/react/pure';
+// eslint-disable-next-line import/no-unresolved
+import { view, store, autoEffect } from 'react-easy-state';
+
+describe('AutoEffect edge cases and errors', () => {
+  afterEach(cleanup);
+
+  test(`Using autoEffect in a function component ${
+    process.env.NOHOOK
+      ? 'with a version of react that has no hooks should'
+      : 'should not'
+  } throw an error`, () => {
+    const someEffect = () => {};
+
+    const MyComp = view(() => {
+      const person = store({ name: 'Bob' });
+      autoEffect(() => someEffect(person.name));
+      return <div>{person.name}</div>;
+    });
+
+    if (process.env.NOHOOK) {
+      expect(() => render(<MyComp />)).toThrow(
+        'You cannot use autoEffect inside a function component with a pre-hooks version of React. Please update your React version to at least v16.8.0 to use this feature.',
+      );
+    } else {
+      expect(() => render(<MyComp />)).not.toThrow();
+    }
+  });
+
+  test('Using autoEffect inside a render of a class component should throw an error', () => {
+    const someEffect = () => {};
+    const person = store({ name: 'Bob' });
+
+    const MyComp = view(
+      class extends Component {
+        render() {
+          autoEffect(() => someEffect(person.name));
+          return <div>{person.name}</div>;
+        }
+      },
+    );
+
+    expect(() => render(<MyComp />)).toThrow(
+      'You cannot use autoEffect inside a render of a class component. Please use it in the constructor or lifecycle methods instead.',
+    );
+  });
+});
diff --git a/__tests__/autoEffect.test.jsx b/__tests__/autoEffect.test.jsx
new file mode 100644
index 0000000..7984d19
--- /dev/null
+++ b/__tests__/autoEffect.test.jsx
@@ -0,0 +1,95 @@
+import React from 'react';
+import { render, cleanup, act } from '@testing-library/react/pure';
+import {
+  view,
+  store,
+  autoEffect,
+  clearEffect,
+  // eslint-disable-next-line import/no-unresolved
+} from 'react-easy-state';
+
+describe.only('autoEffect', () => {
+  afterEach(cleanup);
+
+  test('should auto run global effects', () => {
+    let documentTitle = '';
+    const app = store({ name: 'Online Store' });
+
+    const effect = autoEffect(() => {
+      documentTitle = app.name;
+    });
+    expect(documentTitle).toBe('Online Store');
+
+    act(() => {
+      app.name = 'Learning Platform';
+    });
+    expect(documentTitle).toBe('Learning Platform');
+
+    clearEffect(effect);
+    act(() => {
+      app.name = 'Social Platform';
+    });
+    expect(documentTitle).toBe('Learning Platform');
+  });
+
+  test('should auto run local effects in function components', () => {
+    let documentTitle = '';
+
+    const app = store({ name: 'Online Store' });
+
+    const MyComp = view(() => {
+      autoEffect(() => {
+        documentTitle = app.name;
+      });
+      return <div>{app.name}</div>;
+    });
+
+    const { container, unmount } = render(<MyComp />);
+    expect(container).toHaveTextContent('Online Store');
+    expect(documentTitle).toBe('Online Store');
+
+    act(() => {
+      app.name = 'Learning Platform';
+    });
+    expect(container).toHaveTextContent('Learning Platform');
+    expect(documentTitle).toBe('Learning Platform');
+
+    unmount();
+    act(() => {
+      app.name = 'Social Platform';
+    });
+    expect(documentTitle).toBe('Learning Platform');
+  });
+
+  test('should be recreated on dependency changes in function components', () => {
+    let documentTitle = '';
+
+    const app = store({ name: 'Store' });
+
+    const MyComp = view(({ name }) => {
+      autoEffect(() => {
+        documentTitle = `${name} ${app.name}`;
+      }, [name]);
+      return (
+        <div>
+          {name}
+          {app.name}
+        </div>
+      );
+    });
+
+    const { container, rerender } = render(<MyComp name="Online" />);
+    expect(container).toHaveTextContent('Online Store');
+    expect(documentTitle).toBe('Online Store');
+
+    rerender(<MyComp name="Awesome" />);
+    expect(container).toHaveTextContent('Awesome Store');
+    expect(documentTitle).toBe('Awesome Store');
+
+    act(() => {
+      app.name = 'Page';
+    });
+    expect(container).toHaveTextContent('Awesome Page');
+    expect(documentTitle).toBe('Awesome Page');
+  });
+});
